% %% Initialize% % do initialize first in main.m% clear % %clc% %tmp = matlab.desktop.editor.getActive;% %cd(fileparts(tmp.Filename));% %% 単機牽引用の変数% clear% syms p1 p2 p3 dp1 dp2 dp3 q0 q1 q2 q3 o1 o2 o3 real% syms u1 u2 u3 u4 T1 T2 T3 T4 real% syms R real% syms m l jx jy jz gravity km1 km2 km3 km4 k1 k2 k3 k4 Lx Ly lx ly lz rotor_r cableL real% syms mL real % % syms pl1 pl2 pl3 dpl1 dpl2 dpl3 ol1 ol2 ol3 real% syms pT1 pT2 pT3 real% e3=[0;0;1];                         % z directional unit vector% p	= [  p1;  p2;  p3];             % Position　：xb : 進行方向，zb ：ホバリング時に上向き% dp	= [ dp1; dp2; dp3];             % Velocity% q	= [  q0;  q1;  q2;  q3];        % Quaternion% ob	= [  o1;  o2;  o3];             % Angular velocity% pl  = [ pl1; pl2; pl3];             % Load position% dpl = [dpl1;dpl2;dpl3];             % Load velocity% ol  = [ ol1; ol2; ol3];             % Load angular velocity% pT  = [ pT1; pT2; pT3];             % String position% [Rb0,L] = RodriguesQuaternion(q);   % Rotation matrix% U = [u1;u2;u3;u4];                  % Thrust force ：正がzb 向き% %オイラー角をクオータニオンに変換% syms roll pitch yaw droll dpitch dyaw real% Eq0 = cos(roll/2)*cos(pitch/2)*cos(yaw/2) + sin(roll/2)*sin(pitch/2)*sin(yaw/2);% Eq1 = sin(roll/2)*cos(pitch/2)*cos(yaw/2) - cos(roll/2)*sin(pitch/2)*sin(yaw/2);% Eq2 = cos(roll/2)*sin(pitch/2)*cos(yaw/2) + sin(roll/2)*cos(pitch/2)*sin(yaw/2);% Eq3 = cos(roll/2)*cos(pitch/2)*sin(yaw/2) - sin(roll/2)*sin(pitch/2)*cos(yaw/2);% Eq = [Eq0;Eq1;Eq2;Eq3];% [ERb0,EL] = RodriguesQuaternion(Eq) ;% er = [roll;pitch;yaw];% dP=jacobian(Eq,er);% dER=solve(dP*[droll;dpitch;dyaw]==EL'*ob/2,[droll dpitch dyaw]);% der = simplify([dER.droll;dER.dpitch;dER.dyaw]);% Ib = diag([jx,jy,jz]);% dq = L'*ob/2;% %% With load model 階層型線形化用論文通りのモデル% physicalParam = {m, Lx, Ly lx ly, jx, jy, jz, gravity, km1, km2, km3, km4, k1, k2, k3, k4,rotor_r,mL, cableL};% % dol  = cross(-pT,u1*Rb0*e3)/(m*cableL); % ケーブル角加速度% dpT  = cross(ol,pT); % 機体から見たケーブル上の単位長さの位置の速度% ddpT = cross(dol,pT)+cross(ol,dpT); % 単位長さの位置の加速度% ddpl  = [0;0;-gravity]+(dot(pT,u1*Rb0*e3)-m*cableL*dot(dpT,dpT))*pT/(m+mL); % 牽引物体の加速度% ddp  = ddpl-cableL*ddpT;% dob  = inv(Ib)*cross(-ob,Ib*ob)+inv(Ib)*[u2;u3;u4];%ケーブルの張力は未考慮% x=[q;ob;pl;dpl;pT;ol];% f=[dq;dob;dpl;ddpl;dpT;dol];% Fl= subs(f,U,[0;0;0;0]);% Gl =  [subs(subs(f,[u2;u3;u4],[0;0;0]),u1,1)-Fl, subs(subs(f,[u1;u3;u4],[0;0;0]),u2,1)-Fl, subs(subs(f,[u2;u1;u4],[0;0;0]),u3,1)-Fl, subs(subs(f,[u2;u3;u1],[0;0;0]),u4,1)-Fl];    % simplify(f - (Fl+Gl*U))% matlabFunction_with_input_order(Fl,'file','FL','vars',{x cell2sym(physicalParam)},'outputs',{'dxf'});% matlabFunction_with_input_order(Gl,'file','GL','vars',{x cell2sym(physicalParam)},'outputs',{'dxg'});% matlabFunction_with_input_order(f,'file','with_load_model','vars',{x U cell2sym(physicalParam)},'outputs',{'dx'});% %% 質量推定+x,y外乱込みのモデル(コントローラ設計用)% syms dstx dsty real% physicalParam = {m, Lx, Ly lx ly, jx, jy, jz, gravity, km1, km2, km3, km4, k1, k2, k3, k4, rotor_r, mL, cableL,dstx,dsty};% dol  = cross(-pT,u1*Rb0*e3)/(m*cableL); % ケーブル角加速度% dpT  = cross(ol,pT); % 機体から見たケーブル上の単位長さの位置の速度% ddpT = cross(dol,pT)+cross(ol,dpT); % 単位長さの位置の加速度% ddpl  = [0;0;-gravity]+(dot(pT,u1*Rb0*e3)-m*cableL*dot(dpT,dpT))*pT/(m+mL) + [dstx;dsty;0]; % 牽引物体の加速度% ddp  = ddpl-cableL*ddpT;% dob  = inv(Ib)*cross(-ob,Ib*ob)+inv(Ib)*[u2;u3;u4];%ケーブルの張力は未考慮% % x=[q;ob;pl;dpl;pT;ol];% f=[dq;dob;dpl;ddpl;dpT;dol];% Fl = subs(f,U,[0;0;0;0]);% Gl =  [subs(subs(f,[u2;u3;u4],[0;0;0]),u1,1)-Fl, subs(subs(f,[u1;u3;u4],[0;0;0]),u2,1)-Fl, subs(subs(f,[u2;u1;u4],[0;0;0]),u3,1)-Fl, subs(subs(f,[u2;u3;u1],[0;0;0]),u4,1)-Fl];    % simplify(f - (Fl+Gl*U))% matlabFunction_with_input_order(Fl,'file','FLxyDst','vars',{x cell2sym(physicalParam)},'outputs',{'dxf'});% matlabFunction_with_input_order(Gl,'file','GLxyDst','vars',{x cell2sym(physicalParam)},'outputs',{'dxg'});% % %% Local functions% function m = Mtake(mat,m,n)%     m = mat(m,n);% end%% Initialize% do initialize first in main.mclear %clc%tmp = matlab.desktop.editor.getActive;%cd(fileparts(tmp.Filename));%% 単機牽引用の変数clear% syms p1 p2 p3 dp1 dp2 dp3 q0 q1 q2 q3 o1 o2 o3 realsyms p1 p2 p3 dp1 dp2 dp3 real% syms u1 u2 u3 u4 T1 T2 T3 T4 realsyms u1 u2 u3 real% syms R realsyms m l jx jy jz gravity km1 km2 km3 km4 k1 k2 k3 k4 Lx Ly lx ly lz rotor_r cableL realsyms mL real % syms pl1 pl2 pl3 dpl1 dpl2 dpl3 ol1 ol2 ol3 realsyms pT1 pT2 pT3 reale3=[0;0;1];                         % z directional unit vectorp	= [  p1;  p2;  p3];             % Position　：xb : 進行方向，zb ：ホバリング時に上向き% dp	= [ dp1; dp2; dp3];             % Velocity% q	= [  q0;  q1;  q2;  q3];        % Quaternion% ob	= [  o1;  o2;  o3];             % Angular velocitypl  = [ pl1; pl2; pl3];             % Load positiondpl = [dpl1;dpl2;dpl3];             % Load velocityol  = [ ol1; ol2; ol3];             % Load angular velocitypT  = [ pT1; pT2; pT3];             % String position% [Rb0,L] = RodriguesQuaternion(q);   % Rotation matrixU = [u1;u2;u3];                  % force% %オイラー角をクオータニオンに変換% syms roll pitch yaw droll dpitch dyaw real% Eq0 = cos(roll/2)*cos(pitch/2)*cos(yaw/2) + sin(roll/2)*sin(pitch/2)*sin(yaw/2);% Eq1 = sin(roll/2)*cos(pitch/2)*cos(yaw/2) - cos(roll/2)*sin(pitch/2)*sin(yaw/2);% Eq2 = cos(roll/2)*sin(pitch/2)*cos(yaw/2) + sin(roll/2)*cos(pitch/2)*sin(yaw/2);% Eq3 = cos(roll/2)*cos(pitch/2)*sin(yaw/2) - sin(roll/2)*sin(pitch/2)*cos(yaw/2);% Eq = [Eq0;Eq1;Eq2;Eq3];% [ERb0,EL] = RodriguesQuaternion(Eq) ;% er = [roll;pitch;yaw];% dP=jacobian(Eq,er);% dER=solve(dP*[droll;dpitch;dyaw]==EL'*ob/2,[droll dpitch dyaw]);% der = simplify([dER.droll;dER.dpitch;dER.dyaw]);% Ib = diag([jx,jy,jz]);% dq = L'*ob/2;%% With load model 階層型線形化用論文通りのモデルphysicalParam = {m, Lx, Ly lx ly, jx, jy, jz, gravity, km1, km2, km3, km4, k1, k2, k3, k4,rotor_r,mL, cableL};% dol  = cross(-pT,u1*Rb0*e3)/(m*cableL); % ケーブル角加速度% dpT  = cross(ol,pT); % 機体から見たケーブル上の単位長さの位置の速度% ddpT = cross(dol,pT)+cross(ol,dpT); % 単位長さの位置の加速度% ddpl  = [0;0;-gravity]+(dot(pT,u1*Rb0*e3)-m*cableL*dot(dpT,dpT))*pT/(m+mL); % 牽引物体の加速度% ddp  = ddpl-cableL*ddpT;% dob  = inv(Ib)*cross(-ob,Ib*ob)+inv(Ib)*[u2;u3;u4];%ケーブルの張力は未考慮dol  = cross(-pT, U) / (m * cableL);                 % ケーブル角加速度dpT  = cross(ol, pT);                               % ケーブル単位ベクトルの変化率ddpT = cross(dol, pT) + cross(ol, dpT);              % ケーブル単位ベクトルの2階微分ddpl = [0; 0; -gravity] + (dot(pT, U) - m * cableL * dot(dpT, dpT)) * pT / (m + mL); % 牽引物体の加速度% x=[q;ob;pl;dpl;pT;ol];% f=[dq;dob;dpl;ddpl;dpT;dol];% 12次元の状態ベクトル x_cbf = [pl; dpl; pT; ol]x = [pl; dpl; pT; ol];f = [dpl; ddpl; dpT; dol];% Fl= subs(f,U,[0;0;0;0]);Fl= subs(f,U,[0;0;0]);% Gl =  [subs(subs(f,[u2;u3;u4],[0;0;0]),u1,1)-Fl, subs(subs(f,[u1;u3;u4],[0;0;0]),u2,1)-Fl, subs(subs(f,[u2;u1;u4],[0;0;0]),u3,1)-Fl, subs(subs(f,[u2;u3;u1],[0;0;0]),u4,1)-Fl]; Gl = jacobian(f, U);simplify(f - (Fl+Gl*U))matlabFunction_with_input_order(Fl,'file','FL_CBF','vars',{x cell2sym(physicalParam)},'outputs',{'dxf'});matlabFunction_with_input_order(Gl,'file','GL_CBF','vars',{x cell2sym(physicalParam)},'outputs',{'dxg'});%% 質量推定+x,y外乱込みのモデル(コントローラ設計用)syms dstx dsty realphysicalParam = {m, Lx, Ly lx ly, jx, jy, jz, gravity, km1, km2, km3, km4, k1, k2, k3, k4, rotor_r, mL, cableL,dstx,dsty};% dol  = cross(-pT,u1*Rb0*e3)/(m*cableL); % ケーブル角加速度% dpT  = cross(ol,pT); % 機体から見たケーブル上の単位長さの位置の速度% ddpT = cross(dol,pT)+cross(ol,dpT); % 単位長さの位置の加速度% ddpl  = [0;0;-gravity]+(dot(pT,u1*Rb0*e3)-m*cableL*dot(dpT,dpT))*pT/(m+mL) + [dstx;dsty;0]; % 牽引物体の加速度% ddp  = ddpl-cableL*ddpT;% dob  = inv(Ib)*cross(-ob,Ib*ob)+inv(Ib)*[u2;u3;u4];%ケーブルの張力は未考慮dol  = cross(-pT, U) / (m * cableL);                 % ケーブル角加速度dpT  = cross(ol, pT);                               % ケーブル単位ベクトルの変化率ddpT = cross(dol, pT) + cross(ol, dpT);              % ケーブル単位ベクトルの2階微分ddpl = [0; 0; -gravity] + (dot(pT, U) - m * cableL * dot(dpT, dpT)) * pT / (m + mL) + [dstx;dsty;0]; % 牽引物体の加速度% % x=[q;ob;pl;dpl;pT;ol];% f=[dq;dob;dpl;ddpl;dpT;dol];x = [pl; dpl; pT; ol];f = [dpl; ddpl; dpT; dol];% Fl = subs(f,U,[0;0;0;0]);Fl= subs(f,U,[0;0;0]);% Gl =  [subs(subs(f,[u2;u3;u4],[0;0;0]),u1,1)-Fl, subs(subs(f,[u1;u3;u4],[0;0;0]),u2,1)-Fl, subs(subs(f,[u2;u1;u4],[0;0;0]),u3,1)-Fl, subs(subs(f,[u2;u3;u1],[0;0;0]),u4,1)-Fl];Gl =  jacobian(f, U);   simplify(f - (Fl+Gl*U))matlabFunction_with_input_order(Fl,'file','FLxyDst_CBF','vars',{x cell2sym(physicalParam)},'outputs',{'dxf'});matlabFunction_with_input_order(Gl,'file','GLxyDst_CBF','vars',{x cell2sym(physicalParam)},'outputs',{'dxg'});%% Local functionsfunction m = Mtake(mat,m,n)m = mat(m,n);end